import json,math
from pathlib import Path
from shapely.geometry import Polygon
root=Path('audit/alpha_epsilon_pi')
data=json.loads((root/'purdue_gis_features_fid754_821.json').read_text(encoding='utf-8-sig'))
byid={f['properties']['FID']:f for f in data['features']}
lat0,lon0=40.4274,-86.9137
sx=111412.84*math.cos(math.radians(lat0)); sy=111040.0
records={}
for fid in (754,821):
 f=byid[fid]; ring=f['geometry']['coordinates'][0][:-1]
 xy=[((x-lon0)*sx,(y-lat0)*sy) for x,y in ring]
 p=Polygon(xy); c=p.centroid
 records[str(fid)]={"official_gis_attributes":f['properties'],"local_approx_geometry_metrics":{"vertex_count":len(ring),"area_m2":p.area,"perimeter_m":p.length,"bounds_m":[list(p.bounds[:2]),list(p.bounds[2:])],"centroid_lonlat":[c.x/sx+lon0,c.y/sy+lat0],"placement_origin_xy_m":[c.x,c.y]}}
manifest=json.loads((root/'imagery_tile_manifest.json').read_text(encoding='utf-8-sig'))
address=manifest['points'][1]
loc=records['754']['local_approx_geometry_metrics']['centroid_lonlat']
# Approximate distance to the OSM address label, local tangent plane at Purdue latitude.
dx=(address['lon']-loc[0])*sx;dy=(address['lat']-loc[1])*sy
